B.cP_=new A.cp("\u0627\u0644\u0623\u0646\u0628\u0648\u0628 \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0623\u0635\u063a\u0631 \u0645\u0646 \u0627\u0644\u0628\u0626\u0631","The pipe must be smaller than the hole")
B.acL=new A.cp("\u0627\u0644\u0623\u0646\u0628\u0648\u0628 \u0627\u0644\u062f\u0627\u062e\u0644\u064a \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0623\u0635\u063a\u0631 \u0645\u0646 \u0627\u0644\u062e\u0627\u0631\u062c\u064a","The inner pipe must be smaller than the outer one")
