B.cP7=new A.cp("\u0627\u0644\u0633\u0639\u0629 \u0644\u0627\u0632\u0645 \u062a\u0643\u0648\u0646 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0635\u0641\u0631","Capacity must be greater than zero")
B.cP8=new A.cp("\u0627\u0644\u0642\u0637\u0631 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0644\u0644\u0623\u0646\u0628\u0648\u0628 \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0623\u0635\u063a\u0631 \u0645\u0646 \u0642\u0637\u0631 \u0627\u0644\u0628\u0626\u0631","Pipe OD must be smaller than the hole size")
